"""Dynamics generated by the unsquared octonion associator transports.

Gate 10 showed that the Gram projectors P=M^T M/4 all commute. The signed transport
operators M themselves retain orientation information. For one representative
source pair on each Fano line, this gate proves:

* M^T=-M and M^2=-4P, so exp(tM) is an orthogonal/unitary evolution;
* the seven M are independent and noncommuting;
* their first commutators enlarge the span from 7 to 18 dimensions;
* the next commutator closure reaches all 21 dimensions of so(7).

Thus octonion associators can generate arbitrary SO(7) rotations. This establishes
kinematic controllability, not a prediction: source choices, pulse angles, and
ordering remain free, and generic skew controls also generate so(7).

Run:
    PYTHONDONTWRITEBYTECODE=1 python3 experiments/theory_crucible/associator_transport_dynamics_gate.py
"""

from __future__ import annotations

from itertools import combinations

import numpy as np

from associator_discriminator_gate import transport_defect
from associator_quantum_measurement_gate import (
    associator_projector,
    source_line,
)
from signed_fano_multiplication_census import multiplication_table


def matrix_span_rank(matrices: list[np.ndarray] | tuple[np.ndarray, ...]) -> int:
    vectors = np.column_stack([matrix.reshape(-1) for matrix in matrices])
    return int(np.linalg.matrix_rank(vectors.astype(float), tol=1e-9))


def independent_basis(matrices: list[np.ndarray]) -> list[np.ndarray]:
    basis: list[np.ndarray] = []
    current_rank = 0
    for matrix in matrices:
        candidate_rank = matrix_span_rank(basis + [matrix])
        if candidate_rank > current_rank:
            basis.append(matrix)
            current_rank = candidate_rank
    return basis


def commutator(first: np.ndarray, second: np.ndarray) -> np.ndarray:
    return first @ second - second @ first


def lie_closure_dimensions(generators: tuple[np.ndarray, ...]) -> tuple[int, ...]:
    basis = independent_basis(list(generators))
    dimensions = [len(basis)]
    while True:
        brackets = [
            commutator(first, second) for first, second in combinations(basis, 2)
        ]
        enlarged = independent_basis(basis + brackets)
        dimensions.append(len(enlarged))
        if len(enlarged) == len(basis):
            return tuple(dimensions)
        basis = enlarged


def line_generators(table: np.ndarray) -> tuple[np.ndarray, ...]:
    """Choose one oriented transport generator for each of the seven lines."""
    by_line: dict[tuple[int, ...], np.ndarray] = {}
    for first, second in combinations(range(1, 8), 2):
        line = tuple(sorted(source_line(first, second)))
        by_line.setdefault(
            line, transport_defect(table, first, second).astype(float)
        )
    return tuple(by_line[line] for line in sorted(by_line))


def transport_unitary(generator: np.ndarray, time: float) -> np.ndarray:
    """Closed exponential for M^3=-4M: exp(tM)."""
    identity = np.eye(generator.shape[0])
    return (
        identity
        + 0.5 * np.sin(2.0 * time) * generator
        + 0.25 * (1.0 - np.cos(2.0 * time)) * (generator @ generator)
    )


def elementary_so7_basis() -> tuple[np.ndarray, ...]:
    basis = []
    for first, second in combinations(range(7), 2):
        matrix = np.zeros((7, 7))
        matrix[first, second] = 1.0
        matrix[second, first] = -1.0
        basis.append(matrix)
    return tuple(basis)


def random_skew_generators(
    rng: np.random.Generator, count: int = 7
) -> tuple[np.ndarray, ...]:
    generators = []
    for _ in range(count):
        matrix = rng.normal(size=(7, 7))
        generators.append(matrix - matrix.T)
    return tuple(generators)


def main() -> None:
    table = multiplication_table((1,) * 7)
    generators = line_generators(table)
    assert len(generators) == 7

    for generator in generators:
        assert np.array_equal(generator.T, -generator)
        projector = -(generator @ generator) / 4.0
        assert np.array_equal(projector @ projector, projector)
        assert int(round(np.trace(projector))) == 4

    commutator_norms = tuple(
        np.linalg.norm(commutator(first, second))
        for first, second in combinations(generators, 2)
    )
    commuting_pairs = sum(norm < 1e-12 for norm in commutator_norms)
    noncommuting_pairs = sum(norm >= 1e-12 for norm in commutator_norms)
    assert (commuting_pairs, noncommuting_pairs) == (4, 17)
    assert {round(norm, 12) for norm in commutator_norms} == {0.0, 8.0}

    closure_dimensions = lie_closure_dimensions(generators)
    assert closure_dimensions == (7, 18, 21, 21)
    assert matrix_span_rank(list(elementary_so7_basis())) == 21

    unitarity_residual = 0.0
    noncommuting_evolution = 0.0
    for time in (0.1, 0.3, 0.7, 1.1):
        unitaries = tuple(
            transport_unitary(generator, time) for generator in generators
        )
        unitarity_residual = max(
            unitarity_residual,
            max(
                np.linalg.norm(unitary.T @ unitary - np.eye(7))
                for unitary in unitaries
            ),
        )
        noncommuting_evolution = max(
            noncommuting_evolution,
            max(
                np.linalg.norm(first @ second - second @ first)
                for first, second in combinations(unitaries, 2)
            ),
        )
    assert unitarity_residual < 1e-12
    assert noncommuting_evolution > 1e-3

    rng = np.random.default_rng(20260714)
    random_closures = tuple(
        lie_closure_dimensions(random_skew_generators(rng)) for _ in range(12)
    )
    assert all(dimensions[-1] == 21 for dimensions in random_closures)

    print("=" * 74)
    print("THEORY CRUCIBLE 11: ASSOCIATOR TRANSPORT DYNAMICS")
    print("=" * 74)
    print(f"independent octonion generators      : {len(generators)}")
    print(f"Lie-closure dimensions               : {closure_dimensions}")
    print(f"dim so(7)                            : 21")
    print(f"commuting / noncommuting pairs       : {commuting_pairs} / {noncommuting_pairs}")
    print(f"nonzero commutator norm              : 8")
    print(f"finite-evolution unitarity residual  : {unitarity_residual:.3e}")
    print(f"finite-evolution noncommutativity     : {noncommuting_evolution:.3f}")
    print(f"generic skew controls reaching so(7) : {sum(row[-1] == 21 for row in random_closures)} / {len(random_closures)}")
    print()
    print("PROVED")
    print("  * Each signed associator transport generates valid orthogonal/unitary")
    print("    evolution on its four-dimensional active subspace.")
    print("  * The seven line generators do not commute.")
    print("  * Their Lie closure is the full 21-dimensional rotation algebra so(7),")
    print("    so suitable sequences can generate arbitrary real seven-state rotations.")
    print()
    print("NOT PROVED")
    print("  * which generator, duration, or sequence nature chooses;")
    print("  * a preferred Hamiltonian, initial state, or physical seven-state carrier;")
    print("  * an octonion-specific prediction from controllability alone; generic")
    print("    skew generators also close to so(7).")
    print()
    print("VERDICT: the unsquared associator restores genuine noncommuting quantum")
    print("         kinematics, but full controllability creates freedom rather than")
    print("         a prediction. A dynamics or cost principle must select one path.")


if __name__ == "__main__":
    main()